import{_ as t,o as a,c as o,ah as r}from"./chunks/framework.ojwJKwrc.js";const p=JSON.parse('{"title":"Release policy","description":"","frontmatter":{},"headers":[],"relativePath":"releasing.md","filePath":"releasing.md"}'),s={name:"releasing.md"};function n(l,e,i,c,d,h){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="release-policy" tabindex="-1">Release policy <a class="header-anchor" href="#release-policy" aria-label="Permalink to &quot;Release policy&quot;">​</a></h1><p>Celox is released as one lockstep npm distribution. <code>VERSION</code>, <code>.release-please-manifest.json</code>, <code>@celox-sim/celox</code>, <code>@celox-sim/celox-napi</code>, and <code>@celox-sim/vite-plugin</code> must always carry the same version. Rust workspace crates are internal implementation units, use version <code>0.0.0</code>, and are not published to crates.io.</p><h2 id="versioning-before-1-0" tabindex="-1">Versioning before 1.0 <a class="header-anchor" href="#versioning-before-1-0" aria-label="Permalink to &quot;Versioning before 1.0&quot;">​</a></h2><p>Pull request titles are the input to release automation:</p><table tabindex="0"><thead><tr><th>Pull request title</th><th>Release effect</th></tr></thead><tbody><tr><td><code>fix:</code>, <code>feat:</code>, <code>perf:</code>, <code>revert:</code></td><td>Patch release</td></tr><tr><td>Any allowed type with <code>!</code>, such as <code>feat(api)!:</code></td><td>Minor release</td></tr><tr><td><code>build:</code>, <code>chore:</code>, <code>ci:</code>, <code>docs:</code>, <code>refactor:</code>, <code>test:</code></td><td>No release</td></tr></tbody></table><p>After 1.0, normal Semantic Versioning applies: fixes are patch releases, features are minor releases, and breaking changes are major releases.</p><h2 id="automated-release-train" tabindex="-1">Automated release train <a class="header-anchor" href="#automated-release-train" aria-label="Permalink to &quot;Automated release train&quot;">​</a></h2><p>Release Please maintains one release pull request against <code>master</code>. Every Monday at 03:00 UTC, the release workflow enables auto-merge for that pull request. The required checks and merge queue decide when it is safe to merge. If there are no releasable changes, the run is a no-op.</p><p>The commit that introduces this policy is the release-history baseline. Earlier commits after <code>v0.1.34</code> are intentionally not retroactively classified; release automation starts with pull requests merged after this policy lands.</p><p>Add the <code>release:hold</code> label to the release pull request to keep it out of the weekly train. Run the <strong>Release Management</strong> workflow manually to queue an unheld release immediately.</p><p>Merging the release pull request changes <code>.release-please-manifest.json</code>; that push, rather than a tag push, starts the NAPI build and npm publication workflow. Release Please may still create an immutable version tag and GitHub Release as release metadata, but tags are not deployment triggers.</p><h2 id="veryl-dependency-lanes" tabindex="-1">Veryl dependency lanes <a class="header-anchor" href="#veryl-dependency-lanes" aria-label="Permalink to &quot;Veryl dependency lanes&quot;">​</a></h2><p><code>master</code> is the release lane. It always uses released Veryl crates and is the only source of Celox releases. Renovate groups those crates into one <code>fix(veryl):</code> pull request. A trusted <code>pull_request_target</code> workflow downloads the matching <code>veryl-metadata</code> crate, reapplies the <code>git-command</code>-only default, refreshes <code>Cargo.lock</code> in an isolated container, and pushes the result back to the Renovate branch. The normal lint job rejects a stale or incorrectly featured vendor copy, so the initial Renovate commit cannot race ahead of synchronization. After a three-day release-age guard, required CI checks passing causes that pull request to merge automatically. Its <code>fix</code> title then creates a Celox patch in the next automated release train. The complete HEAD-to-Veryl-release-to-Celox- release path therefore needs no routine manual step; a compatibility failure simply stops at the required checks.</p><p><code>integration/veryl-head</code> is a generated, non-release branch. <strong>Veryl HEAD Integration</strong> recreates it from the latest <code>master</code> every day and whenever the stable dependency definition changes, pins all Veryl crates to one exact commit from upstream <code>master</code>, and lets the normal CI workflow test that commit. A failure on this branch is an early compatibility signal; do not merge or release this branch. The next successful run replaces it, so work on failures in a separate pull request or git worktree.</p><h2 id="repository-configuration" tabindex="-1">Repository configuration <a class="header-anchor" href="#repository-configuration" aria-label="Permalink to &quot;Repository configuration&quot;">​</a></h2><p>The release workflow requires a <code>RELEASE_PLEASE_TOKEN</code> Actions secret containing a fine-grained token or GitHub App token with repository contents and pull request write access. The Veryl HEAD and vendored-metadata workflows use the same token to make their generated branch pushes start normal CI. Using the default <code>GITHUB_TOKEN</code> would prevent workflows from running on bot-created pull request updates.</p><p>Configure merge commits to use the pull request title as the merge commit title. This preserves the Conventional Commit title consumed by Release Please. Protect <code>master</code> and require both <strong>Conventional Commit title</strong> and the normal CI checks; do not allow those checks to be bypassed by the weekly release automation. Enable repository auto-merge so the weekly workflow can queue a checked release pull request. Allow the automation token to force-update the disposable <code>integration/veryl-head</code> branch; never grant that exception on <code>master</code>.</p>',17)])])}const m=t(s,[["render",n]]);export{p as __pageData,m as default};
